{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if "threshold" not in case:
        raise ValueError("missing threshold")
    threshold = case["threshold"]
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be number")
    if "calls" not in case:
        raise ValueError("missing calls")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be list")
    diagnostics = []
    accepted_call_ids = []
    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"call at index {i} not dict")
        for key in ["call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"]:
            if key not in call:
                raise ValueError(f"missing {key} in call {i}")
        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        tokens = call["prediction_tokens"]
        parseable = call["parseable"]
        gain = loss_without - loss_with
        norm_gain = gain / max(tokens, 1)
        accepted = (parseable is True) and (norm_gain >= threshold)
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": norm_gain
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }"}
